From 972306b32219efcab79ea1767c53c7acf79f0e4b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:39:38 +0100
Subject: [PATCH] applets/devicenotifier: Hide camera actions for MTP devices

Phones in MTP mode also show up as gphoto cameras, but kio-mtp keeps
them claimed, so camera actions like downloading photos with Gwenview
or digiKam always failed. Don't offer actions that only use the camera.

BUG: 446274
---
 applets/devicenotifier/actionsinfo.cpp | 13 ++++++++++++-
 1 file changed, 12 insertions(+), 1 deletion(-)

diff --git a/applets/devicenotifier/actionsinfo.cpp b/applets/devicenotifier/actionsinfo.cpp
index 92cf83679a..d5e8794ce1 100644
--- a/applets/devicenotifier/actionsinfo.cpp
+++ b/applets/devicenotifier/actionsinfo.cpp
@@ -14,6 +14,7 @@
 #include <Solid/Predicate>

 #include <Solid/OpticalDrive>
+#include <Solid/PortableMediaPlayer>

 #include <KLocalizedString>
 #include <KService>
@@ -212,6 +213,13 @@ void ActionsInfo::updateActionsForPredicates(const QHash<QString, Solid::Predica

     const Solid::Device &device = m_storageInfo->device();

+    // MTP devices are claimed by kio-mtp, so actions that reach them through the camera interface (gphoto) can't work
+    bool supportsMTP = false;
+    if (device.is<Solid::PortableMediaPlayer>()) {
+        auto *mediaplayer = device.as<Solid::PortableMediaPlayer>();
+        supportsMTP = mediaplayer && mediaplayer->supportedProtocols().contains(QLatin1String("mtp"));
+    }
+
     QStringList interestingDesktopFiles;
     // search in all desktop configuration file if the device inserted is a correct device
     QHashIterator it(predicates);
@@ -220,7 +228,10 @@ void ActionsInfo::updateActionsForPredicates(const QHash<QString, Solid::Predica
         it.next();
         if (it.value().matches(device)) {
             m_isEmpty = false;
-            if (blockActions(it.key())) {
+            const QSet<Solid::DeviceInterface::Type> usedTypes = it.value().usedTypes();
+            if (supportsMTP && usedTypes.contains(Solid::DeviceInterface::Camera) && !usedTypes.contains(Solid::DeviceInterface::PortableMediaPlayer)) {
+                qCDebug(APPLETS::DEVICENOTIFIER) << "Actions Info " << device.udi() << " : " << it.key() << " camera action was blocked for MTP device";
+            } else if (blockActions(it.key())) {
                 interestingDesktopFiles << it.key();
             } else {
                 qCDebug(APPLETS::DEVICENOTIFIER) << "Actions Info " << device.udi() << " : " << it.key() << " action was blocked";
